def _close(p, q):
    return len(p) == len(q) and all(abs(a - b) < 1e-9 for a, b in zip(p, q))
def _all_close(ps, qs):
    return len(ps) == len(qs) and all(_close(p, q) for p, q in zip(ps, qs))
